import{z as o,x as i,o as l,c as d,q as r,j as s,D as e,d as E,s as n,S as B,b as A}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"跨模型比较的陷阱","description":"","frontmatter":{"title":"跨模型比较的陷阱","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/aeval-crossmodel-pitfalls.md","filePath":"llm/aeval-crossmodel-pitfalls.md","lastUpdated":1791063341000}'),m={name:"llm/aeval-crossmodel-pitfalls.md"};function p(h,a,D,f,F,C){const t=i("Mermaid");return l(),d("div",null,[a[2]||(a[2]=r('<h1 id="跨模型比较的陷阱" tabindex="-1">跨模型比较的陷阱 <a class="header-anchor" href="#跨模型比较的陷阱" aria-label="Permalink to &quot;跨模型比较的陷阱&quot;">​</a></h1><div class="epigraph"><p>两张榜的差值里，大半不是模型差，是协议差：裁判版本、解码配置、对话模板、题目泄漏，每一个都能搬动名次。</p><footer>—— Zheng et al., Judging LLM-as-a-Judge with MT-Bench and Chatbot Arena 的偏差测量；据公开评测复现报告整理</footer></div><p><a href="/llm/aeval-alignment-tax">上一课</a>把对齐税钉成配对消融与分域剖面——配对是同源比较，混淆可控。对外叙事要的是跨模型比较：不同实验室、不同检查点、不同榜单。混淆从「可控」升级成「四面八方」。本课写陷阱清单与一份把它们逐项钉死的比较协议。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>跨模型比较里的每个「显然」都藏着混淆。<strong>法官偏差</strong>：位置、长度、自我偏好，<a href="/llm/llm-judge-bias">LLM 裁判偏差</a>已列为一等系统误差；裁判升级等于换尺子，时间序列当场断裂。<strong>解码配置</strong>：温度与 top-p 改「偶尔配合」的频率，<a href="/llm/jailbreak">越狱评测</a>量过 ASR 对解码的敏感度；两个模型用不同温度比安全分，比的是采样器。<strong>对话模板与提示格式</strong>：同一权重换模板掉分是常态（见<a href="/llm/chat-template">聊天模板</a>与<a href="/llm/prompt-format-sensitivity">提示格式敏感度</a>），「产品视角」与「协议视角」的数字能差出一个名次。<strong>污染与饱和</strong>：后发布的模型可能背过题，旧榜通胀（见<a href="/llm/eval-contamination">评测污染</a>与<a href="/llm/benchmark-saturation">基准饱和</a>）。<strong>风格混淆</strong>：更长、更自信、更新式文风的输出系统性赢——而这些恰好与新模型相关，名次移动被读成进步。<strong>方差</strong>：不报区间的名次差多半是噪音。缺口不是发现新坑，是把坑变成协议字段。</p><p><span class="marginnote">「harness」就是「考试的整套流程装备」：题面怎么呈现给模型、回答怎么截断、答案怎么抽出来打分。同一份题换一套 harness，就像换一个人批卷——分数差可能比模型本身的差距还大，所以比较协议的第一条永远是冻结它。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="协议-冻结、换序、双族、区间" tabindex="-1">协议：冻结、换序、双族、区间 <a class="header-anchor" href="#协议-冻结、换序、双族、区间" aria-label="Permalink to &quot;协议：冻结、换序、双族、区间&quot;">​</a></h3><p>冻结 harness：模板、解码、截断、判分五件套固定，比较里只换权重。程序判子集先行：有答案键的（数学、代码、抽取）不用法官。法官层双保险：成对换序，不一致记平；换一个家族的法官复算一遍，剖面大洗牌说明原表在奖某一家文风。统计层逐题配对：\\(d_i\\in\\{-1,0,1\\}\\)，胜率 \\(\\hat w=\\frac{1}{n}\\sum[d_i{=}1]\\)，区间 \\(\\hat w \\pm 1.96\\sqrt{\\hat w(1-\\hat w)/n}\\)。最后随结果发布一张偏差审计表：每项混淆，是否控制、怎么控制、没控制的声明。</p>',9)),(l(),s(B,null,{default:e(()=>[n(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20TWO%5B%22%E4%B8%A4%E4%B8%AA%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20SAME%5B%22%E5%90%8C%E6%A8%A1%E6%9D%BF%E5%90%8C%E8%A7%A3%E7%A0%81%E5%90%8C%E6%88%AA%E6%96%AD%22%5D%0A%20%20SAME%20--%3E%20PROG%5B%22%E7%A8%8B%E5%BA%8F%E5%88%A4%E5%AD%90%E9%9B%86%E5%85%88%E8%A1%8C%22%5D%0A%20%20PROG%20--%3E%20JUDGE%5B%22%E6%B3%95%E5%AE%98%EF%BC%9A%E6%8D%A2%E5%BA%8F%20%2B%20%E5%8F%8C%E6%97%8F%E5%AF%B9%E7%85%A7%22%5D%0A%20%20JUDGE%20--%3E%20PAIR%5B%22%E9%80%90%E9%A2%98%E9%85%8D%E5%AF%B9%E5%B7%AE%E5%88%86%20%2B%20%E5%8C%BA%E9%97%B4%22%5D%0A%20%20PAIR%20--%3E%20AUDIT%5B%22%E5%81%8F%E5%B7%AE%E5%AE%A1%E8%AE%A1%E8%A1%A8%22%5D%0A%20%20AUDIT%20--%3E%20TWOVIEW%5B%22%E4%B8%A4%E8%A7%86%E8%A7%92%E6%8A%A5%E5%91%8A%EF%BC%9A%E4%BA%A7%E5%93%81%20%2F%20%E5%8D%8F%E8%AE%AE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[E("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,[E("这些混淆为什么有共同方向：法官的审美（长、全、自信、流利）与新模型的训练趋势相关，偏差不是白噪音而是单向斜坡——每一代都白捡几分，若干代累积出的「进步曲线」里，分不清哪一段是模型、哪一段是尺子。这决定了对策必须是结构性的：换序消灭位置项，程序判消灭风格项，双族对照暴露同族项；"),A("a",{href:"/llm/style-control"},"风格控制"),E("一类后处理能再剥一层，但任何「在提示里写忽略长度」的自然语言禁令都被证明无效。")],-1)),a[5]||(a[5]=A("p",null,"尺子偏向如何伪造进步曲线，以及三个结构性对策各自消灭哪一项：",-1)),(l(),s(B,null,{default:e(()=>[n(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E6%96%B0%E4%B8%80%E4%BB%A3%E6%A8%A1%E5%9E%8B%EF%BC%9A%E6%9B%B4%E9%95%BF%E3%80%81%E6%9B%B4%E8%87%AA%E4%BF%A1%E7%9A%84%E6%96%87%E9%A3%8E%22%5D%20--%3E%20J%5B%22%E6%B3%95%E5%AE%98%E5%AE%A1%E7%BE%8E%EF%BC%9A%E5%81%8F%E7%88%B1%E9%95%BF%20%2F%20%E5%85%A8%20%2F%20%E8%87%AA%E4%BF%A1%22%5D%0A%20%20J%20--%3E%7C%22%E7%B3%BB%E7%BB%9F%E6%80%A7%E5%8A%A0%E5%88%86%22%7C%20B%5B%22%E6%A6%9C%E5%8D%95%E8%AF%BB%E6%95%B0%E6%8A%AC%E5%8D%87%22%5D%0A%20%20B%20--%3E%20CURVE%5B%22%E5%A4%9A%E4%BB%A3%E7%B4%AF%E7%A7%AF%E7%9A%84%E3%80%8C%E8%BF%9B%E6%AD%A5%E6%9B%B2%E7%BA%BF%E3%80%8D%22%5D%0A%20%20CURVE%20--%3E%20Q%7B%22%E5%93%AA%E6%AE%B5%E6%98%AF%E6%A8%A1%E5%9E%8B%E3%80%81%E5%93%AA%E6%AE%B5%E6%98%AF%E5%B0%BA%E5%AD%90%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%8D%A2%E5%BA%8F%E7%81%AD%E4%BD%8D%E7%BD%AE%E9%A1%B9%22%7C%20S%5B%22%E7%BB%93%E6%9E%84%E5%AF%B9%E7%AD%96%E4%B8%89%E4%BB%B6%22%5D%0A%20%20Q%20--%3E%7C%22%E7%A8%8B%E5%BA%8F%E5%88%A4%E7%81%AD%E9%A3%8E%E6%A0%BC%E9%A1%B9%22%7C%20S%0A%20%20Q%20--%3E%7C%22%E5%8F%8C%E6%97%8F%E6%B3%95%E5%AE%98%E7%81%AD%E5%90%8C%E6%97%8F%E9%A1%B9%22%7C%20S%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">初学者容易以为评测偏差是随机的、多测几次就能平均掉。实际上法官偏好是单向的：总是偏爱更长更自信的回答，于是每一代模型都朝这个方向白捡分。随机噪音平均会归零，单向斜坡只会一路累积。</span></p><p><span class="marginnote">区间感的具体数字：\\(n=100\\) 的成对比较，55% 对 45% 的胜率差，95% 区间宽约 \\(\\pm 10\\) 个百分点——多数「新模型又赢了八个点」的头条在统计上站不住；\\(n\\) 到四百，同样的差才勉强出噪音。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>完全公平不可达：每个模型在自己的最优模板上才发挥全部能力，统一模板对某一方必然是降维——所以两视角分列（各自最优 vs 统一协议），并声明选了哪种。内部门禁与对外宣传分开：门禁可以钉死协议拿可复现的差，宣传若要引用外部榜单，审计表一起引用。最后，<a href="/llm/mt-bench">MT-Bench</a> 的教训重申一遍：零点几分的总分差没有意义；本课的协议不保证你比出「谁更好」，只保证比出来的差能被解释。</p><p><span class="marginnote">「各自最优 vs 统一协议」就像让两位厨师各做拿手菜比一次、再做同一道菜比一次：前者看谁上限高，后者看同样条件下谁强。两局结果不同并不矛盾——报数字时要说明自己比的是哪一局。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>跨模型比较的可信度取决于协议字段，不取决于题目难度。</li><li>冻结 harness 只换权重；程序判子集先于法官。</li><li>换序、双族、逐题配对加区间：四个统计件缺一，名次不可解释。</li><li>偏差有方向：长、自信、新文风单向加分，进步曲线要过尺子这一关。</li><li>两视角分列：各自最优模板与统一协议，声明选择，别混表。</li><li>出处：Zheng et al. 的法官偏差测量；公开套件与复现报告口径；本课程协议整理。</li></ul>',7))])}const g=o(m,[["render",p]]);export{u as __pageData,g as default};
